fun isBalanced(text: String): Boolean {
    val opened = ArrayDeque<Char>()
    for (ch in text) {
        when (ch) {
            '(', '[', '{' -> opened.addLast(ch)
            ')' -> if (opened.removeLastOrNull() != '(') return false
            ']' -> if (opened.removeLastOrNull() != '[') return false
            '}' -> if (opened.removeLastOrNull() != '{') return false
        }
    }
    return opened.isEmpty()
}

fun main() {
    for (text in listOf("([])", "([)]", "(((", ")(", "", "{[()]}")) {
        println("\"$text\" -> ${isBalanced(text)}")
    }
}

