fun isBalanced(text: String): Boolean {
    var depth = 0
    for (ch in text) {
        if (ch == '(' || ch == '[') {
            depth++
        }
        if (ch == ')' || ch == ']') {
            depth--
        }
        if (depth < 0) {
            return false
        }
    }
    return depth == 0
}

fun main() {
    val samples = listOf("([])", "([)]", "(()", "())(")
    for (sample in samples) {
        println("$sample -> ${isBalanced(sample)}")
    }
}

